-- UKPSC Test Platform — Phase 44: replace a deactivated question in CA Revision 6, keep flagged questions out of Telegram
-- Safe to re-run. No DROP / DELETE / TRUNCATE.
-- Run AFTER: npx.cmd --yes tsx scripts/load-question-bank.mts --apply
--
-- 1. The loader replaced UKPCS-UKGK-CH09-0161 in Uttarakhand CA + Budget (TEST_OVERRIDES.xlsx).
--    CA Revision 6 is a copy outside the loader, so it gets the same swap here.
-- 2. Every question with a Review_Flag in the workbooks is set inactive, unless it is in a test.
--    The Telegram daily quiz (telegram_unused_questions) takes active questions in no test, and the
--    loader never updates status, so flagged questions stayed active and could be posted.
--    To bring one back later: clear its Review_Flag AND set its status to 'active' in the database.
--
-- A student's past attempt keeps its own question list, and results read questions whatever their
-- status, so old results are not affected.

-- ========== 1. CA Revision 6 ==========
with resolved as (
  select o.id as old_id, n.id as new_id
  from questions o, questions n
  where o.question_id = 'UKPCS-UKGK-CH09-0161' and n.question_id = 'UKPCS-UKGK-CH09-0022'
)
update tests t set
  question_ids = array_replace(t.question_ids, r.old_id, r.new_id),
  updated_at = now()
from resolved r
where t.test_name = 'CA Revision 6'
  and r.old_id = any(t.question_ids)
  and not (r.new_id = any(t.question_ids));

-- ========== 2. Flagged questions: inactive (1149 ids in the workbooks) ==========
update questions q set
  status = 'inactive',
  deactivated_at = now(),
  updated_at = now()
where coalesce(q.status, 'active') <> 'inactive'
  and not exists (select 1 from tests t where q.id = any(t.question_ids))
  and q.question_id in (
